53: 
54:       // Align the stage to top left
55:       stage.align = "TL";
56:       stage.scaleMode = "noScale";
57: 
58:       // Get the flashvars
59:       var flashvars:Object = LoaderInfo( this.root.loaderInfo ).parameters;
60: 
61:       // Allow the SWF object to communicate with a page on a different origin than its own (e.g. SWF served from CDN)
62:       if (flashvars.trustedOrigins && typeof flashvars.trustedOrigins === "string") {
63:         var origins:Array = flashvars.trustedOrigins.split("\\").join("\\\\").split(",");
