65:       }
66:       
67:       // Enable complete AMD support (e.g. RequireJS)
68:       if (flashvars.amdModuleId && typeof flashvars.amdModuleId === "string") {
69:         amdModuleId = flashvars.amdModuleId.split("\\").join("\\\\");
70:       }
71: 
72:       // Enable complete CommonJS support (e.g. Browserify)
73:       if (flashvars.cjsModuleId && typeof flashvars.cjsModuleId === "string") {
74:         cjsModuleId = flashvars.cjsModuleId.split("\\").join("\\\\");
75:       }
76: 
77:       // invisible button covers entire stage
78:       button = new Sprite();
79:       button.buttonMode = true;
80:       button.useHandCursor = false;
81:       button.graphics.beginFill(0xCCFF00);
82:       button.graphics.drawRect(0, 0, stage.stageWidth, stage.stageHeight);
83:       button.alpha = 0.0;
84:       addChild(button);
85: 
86:       // Adding the event listeners
87:       button.addEventListener(MouseEvent.CLICK, mouseClick);
88:       button.addEventListener(MouseEvent.MOUSE_OVER, mouseOver);
89:       button.addEventListener(MouseEvent.MOUSE_OUT, mouseOut);
90:       button.addEventListener(MouseEvent.MOUSE_DOWN, mouseDown);
