93:       // external functions
94:       ExternalInterface.addCallback("setHandCursor", setHandCursor);
95:       ExternalInterface.addCallback("setText", setText);
96:       ExternalInterface.addCallback("setSize", setSize);
97: 
98:       // signal to the browser that we are ready
