102:     // mouseClick
103:     //
104:     // The mouseClick private function handles clearing the clipboard, and
105:     // setting new clip text. It gets this from the clipText private variable.
106:     // Once the text has been placed in the clipboard, It then signals to the
107:     // Javascript that it is done.
108:     //
109:     // returns nothing
110:     private function mouseClick(event:MouseEvent): void {
111: 
112:       // Linux currently doesn't use the correct clipboard buffer with the new
113:       // Flash 10 API, so we need to use this until we can figure out an alternative
114:       flash.system.System.setClipboard(clipText);
115: 
116:       // signal to the page it is done
117:       dispatch("complete", ZeroClipboard.metaData(event, {
118:         text: clipText.split("\\").join("\\\\")
119:       }));
120: 
121:       // reset the text
122:       clipText = "";
123:     }
124: 
125:     // mouseOver
126:     //
127:     // The mouseOver function signals to the page that the button is being hovered.
128:     //
129:     // returns nothing
130:     private function mouseOver(event:MouseEvent): void {
131:       dispatch("mouseOver", ZeroClipboard.metaData(event));
132:     }
133: 
134:     // mouseOut
135:     //
136:     // The mouseOut function signals to the page that the button is not being hovered.
137:     //
138:     // returns nothing
139:     private function mouseOut(event:MouseEvent): void {
140:       dispatch("mouseOut", ZeroClipboard.metaData(event));
141:     }
142: 
143:     // mouseDown
144:     //
145:     // The mouseDown function signals to the page that the button has a mouse button down.
146:     //
147:     // returns nothing
148:     private function mouseDown(event:MouseEvent): void {
149:       dispatch("mouseDown", ZeroClipboard.metaData(event));
150: 
151:       // if the clipText hasn't been set
152:       if (!clipText) {
153:         // request data from the page
154:         dispatch("dataRequested", ZeroClipboard.metaData(event));
155:       }
156:     }
157: 
158:     // mouseUp
159:     //
160:     // The mouseUp function signals to the page that the mouse button has been lifted
161:     //
162:     // returns nothing
163:     private function mouseUp(event:MouseEvent): void {
164:       dispatch("mouseUp", ZeroClipboard.metaData(event));
165:     }
166: 
167:     // setText
168:     //
169:     // setText gets the clipboard text to be copied from the javascript.
170:     //
171:     // returns nothing
172:     public function setText(newText:String): void {
173:       // set the maximum number of files allowed
174:       clipText = newText;
175:     }
176: 
177:     // setHandCursor
178:     //
179:     // setHandCursor will make the button cursor be a hand on hover.
180:     //
181:     // returns nothing
182:     public function setHandCursor(enabled:Boolean): void {
183:       button.useHandCursor = enabled;
184:     }
185: 
186:     // setSize
187:     //
188:     // Sets the size of the button to equal the size of the hovered object.
189:     //
190:     // returns nothing
191:     public function setSize(width:Number, height:Number): void {
192:       button.width = width;
193:       button.height = height;
194:     }
195:     
196:     // dispatch
197:     //
198:     // Function through which JavaScript events are dispatched
199:     //
200:     // returns nothing
201:     private function dispatch(eventName:String, eventArgs:Object): void {
202:       if (amdModuleId) {
203:         ExternalInterface.call(ZeroClipboard.amdWrappedDispatcher, eventName, eventArgs, amdModuleId);
204:       }
205:       else if (cjsModuleId) {
206:         ExternalInterface.call(ZeroClipboard.cjsWrappedDispatcher, eventName, eventArgs, cjsModuleId);
207:       }
208:       else {
209:         ExternalInterface.call(ZeroClipboard.normalDispatcher, eventName, eventArgs);
210:       }
211:     }
